/*
 * A323179  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 30", with accumulating cell values.
 * https://oeis.org/A323179
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 79, u16 n <= 79, u32 n <= 79, u64 n <= 79, u128 n <= 79,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes A323179 – Rule 30 cellular automaton accumulating cell values. */

#include <stdlib.h>
#include <stddef.h>

/* integer square root (floor) for unsigned 64‑bit values. */
static inline idx_t isqrt_u64(idx_t n)
{
    idx_t lo = 0, hi = n, ans = 0;
    while (lo <= hi) {
        idx_t mid = lo + ((hi - lo) >> 1);
        __int128 sq = (__int128)mid * mid;
        if (sq <= n) {
            ans = mid;
            lo  = mid + 1;
        } else {
            if (mid == 0) break;
            hi = mid - 1;
        }
    }
    return ans;
}

seq_t a(idx_t n)
{
    /* Determine the row r and column k of the n‑th flattened term. */
    idx_t r = isqrt_u64(n);               /* r = floor(sqrt(n))   */
    idx_t k = n - r * r;                  /* column index in row r */

    /* Pre‑allocate the maximum row length needed. */
    size_t maxlen = (size_t)(2 * r + 1);
    seq_t *cur  = (seq_t *)malloc(maxlen * sizeof(seq_t));
    seq_t *next = (seq_t *)malloc(maxlen * sizeof(seq_t));
    if (!cur || !next) {
        free(cur);
        free(next);
        return (seq_t)0;
    }

    /* Initialise the first row (row 0). */
    cur[0] = (seq_t)1;
    size_t cur_len = 1;

    /* Generate rows 1 … r. */
    for (idx_t row = 1; row <= r; ++row) {
        size_t new_len = cur_len + 2;  /* each row grows by two cells */

        for (size_t j = 0; j < new_len; ++j) {
            seq_t left   = (j >= 2 && j - 2 < cur_len) ? cur[j - 2] : 0;
            seq_t center = (j >= 1 && j - 1 < cur_len) ? cur[j - 1] : 0;
            seq_t right  = (j < cur_len)                 ? cur[j]     : 0;

            seq_t sum = left + center + right;
            next[j] = (left == 0 || (center == 0 && right == 0)) ? sum : 0;
        }

        /* Swap buffers for the next iteration. */
        seq_t *tmp = cur;
        cur   = next;
        next  = tmp;
        cur_len = new_len;
    }

    /* Retrieve the desired cell value. */
    seq_t result = (k < cur_len) ? cur[(size_t)k] : (seq_t)0;

    /* Clean up. */
    free(cur);
    free(next);
    return result;
}
